var i=`0058-trdelnik`;var t=`world-0058`;var a=`CZ`;var s=`eastern-europe`;var o=6;var r=98;var l={en:`Trdelník`,ua:`Трдельник`};var u={en:`A classic dish from Czechia, featuring whole cow milk, chicken egg, all-purpose flour, instant yeast. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Чехія. Основні складники: цільне коров'яче молоко, куряче яйце, пшеничне борошно універсальне, інстантні дріжджі. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 70 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 70 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:70,i:[[`all-purpose-flour`,400,`g`],[`whole-cow-milk`,180,`ml`],[`instant-yeast`,8,`g`],[`white-granulated-sugar`,70,`g`],[`unsalted-butter`,50,`g`],[`chicken-egg`,1,`pcs`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Roast in a preheated 190°C oven for about 14 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 14 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:14,i:[[`white-granulated-sugar`,75,`g`],[`ground-cinnamon`,7,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,35,`g`]]}];var g={slug:i,id:t,country:`CZ`,region:s,servings:6,minutes:98,title:l,text:u,steps:d};export{a as country,g as default,t as id,r as minutes,s as region,o as servings,i as slug,d as steps,u as text,l as title};